draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // Circle
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 20 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();

  // Lines
  for (let i = 0; i < 10; i++) {
    ctx.beginPath();
    ctx.moveTo(W/2, H/2);
    ctx.lineTo(W/2 + (50 + 20 * Math.sin(t)) * Math.cos(i * Math.PI / 5 + t), 
                H/2 + (50 + 20 * Math.sin(t)) * Math.sin(i * Math.PI / 5 + t));
    ctx.stroke();
  }

  ctx.restore();
}
